<?php declare(strict_types=1); ?>
<section class="panel"><header class="panel-head"><div><span class="eyebrow">Canonical purchase orders</span><h2>Authorized orders</h2><p>Proposed price or delivery changes stay staged until an internal reviewer approves or routes them.</p></div></header><div class="record-list"><?php foreach($pos as $po): ?><article class="record-card"><header><div><strong><?= h($po['po_number']) ?></strong><small><?= h(data_company_name($po['company_id'])) ?> · Ordered <?= h(date_us($po['order_date'])) ?> · Required <?= h(date_us($po['required_date'])) ?></small></div><span class="status <?= h($po['status']) ?>"><?= h(status_label($po['status'])) ?></span></header><p><?= money($po['total_amount']) ?> · Expected <?= h(date_us($po['expected_date'])) ?></p><?php if(supplier_portal_can($account,'acknowledge_po')): ?><form class="form-grid" method="post" action="<?= h(root_url('supplier-portal/action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="submit_po_response"><input type="hidden" name="return_tab" value="orders"><input type="hidden" name="purchase_order_id" value="<?= (int)$po['id'] ?>"><label><span>Response</span><select name="response_type"><option value="accept">Accept PO</option><option value="acknowledge">Acknowledge only</option><option value="change_request">Propose change</option><option value="reject">Reject with evidence</option></select></label><label><span>Proposed delivery</span><input type="date" name="proposed_delivery_date" value="<?= h($po['expected_date']) ?>"></label><label><span>Proposed total</span><input type="number" name="proposed_total_amount" step="0.01" min="0" value="<?= h((string)$po['total_amount']) ?>"></label><label><span>Confirmation reference</span><input name="evidence_reference" required></label><label class="span-2"><span>Response explanation</span><textarea name="notes" required></textarea></label><div class="span-2"><button class="button primary">Submit response</button></div></form><?php endif; ?></article><?php endforeach; ?></div></section>
<section class="panel"><header class="panel-head"><div><span class="eyebrow">Response history</span><h2>Submitted PO responses</h2></div></header><div class="table-wrap"><table><thead><tr><th>Response</th><th>PO</th><th>Type</th><th>Delivery</th><th>Status</th><th>Review note</th></tr></thead><tbody><?php foreach($responses as $r): ?><tr><td><?= h($r['response_number']) ?></td><td>#<?= (int)$r['purchase_order_id'] ?></td><td><?= h(status_label($r['response_type'])) ?></td><td><?= h(date_us($r['proposed_delivery_date'])) ?></td><td><span class="status <?= h($r['status']) ?>"><?= h(status_label($r['status'])) ?></span></td><td><?= h($r['review_note']??'') ?></td></tr><?php endforeach; ?></tbody></table></div></section>
